// le prenom du profil : « , Camille » ; rien s'il manque
let QUI = ''; try { const p = String($env.ARCHI_UTILISATEUR || '').trim().slice(0, 30); if (p) QUI = ', ' + p; } catch (e) {}
// Archi - Catalogues 3D : recherche sur Printables et telechargement des STL
const fs = require('fs');
const inp = $input.first().json.query || $input.first().json;
const action = String(inp.action || 'chercher').toLowerCase().trim();
const API = 'https://api.printables.com/graphql/';
const HEAD = { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36', 'Content-Type': 'application/json' };
const DOSSIER = ($env.ARCHI_BASE || '') + '/impression3d/';
const MEMO = DOSSIER + 'derniere_recherche.json';

const gql = async (operationName, query, variables) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: API, headers: HEAD, body: { operationName, query, variables }, json: true, timeout: 20000 });
  if (r.errors) throw new Error('Printables a refuse la requete : ' + JSON.stringify(r.errors).slice(0, 300));
  return r.data;
};

if (action === 'chercher') {
  const q = String(inp.requete || '').trim();
  if (!q) throw new Error('Recherche vide : donne des mots-cles en anglais.');
  const data = await gql('SearchModels',
    'query SearchModels($query: String!, $limit: Int) { result: searchPrints2(query: $query, printType: print, limit: $limit, ordering: best_match) { items { id name slug likesCount downloadCount user { publicUsername } image { filePath } } } }',
    { query: q, limit: 8 });
  const items = ((data.result || {}).items || []).slice(0, 5).map((m, i) => ({
    n: i + 1, id: String(m.id), nom: m.name, slug: m.slug,
    auteur: (m.user || {}).publicUsername || '?', likes: m.likesCount || 0, telechargements: m.downloadCount || 0,
    lien: 'https://www.printables.com/model/' + m.id + '-' + m.slug,
    image: m.image && m.image.filePath ? 'https://media.printables.com/' + m.image.filePath : null
  }));
  fs.writeFileSync(MEMO, JSON.stringify({ requete: q, date: new Date().toISOString(), resultats: items }, null, 2), 'utf8');
  const texte = items.length
    ? 'Printables, recherche « ' + q + ' » :\n\n' + items.map(m => m.n + '. ' + m.nom + '\n   par ' + m.auteur + ' · ' + m.likes + ' j\'aime · ' + m.telechargements + ' téléchargements\n   ' + m.lien).join('\n\n') + '\n\nRéponds avec le numéro à télécharger, ou dis-moi de la fabriquer moi-même.'
    : 'Printables : aucun modèle trouvé pour « ' + q + ' ».';
  return [{ json: { action, requete: q, nb: items.length, resultats: items, texte } }];
}

if (action === 'telecharger') {
  let id = String(inp.id_modele || '').trim();
  let modele = null;
  if (!id) {
    if (!fs.existsSync(MEMO)) throw new Error('Aucune recherche recente : fais d\'abord une recherche.');
    const memo = JSON.parse(fs.readFileSync(MEMO, 'utf8'));
    const n = parseInt(String(inp.choix || '').replace(/\D/g, ''), 10);
    modele = (memo.resultats || []).find(m => m.n === n);
    if (!modele) throw new Error('Numero ' + inp.choix + ' introuvable dans la derniere recherche (1 a ' + (memo.resultats || []).length + ').');
    id = modele.id;
  }
  const data = await gql('ModelFiles', 'query ModelFiles($id: ID!) { model: print(id: $id) { id name slug stls { id name fileSize } } }', { id });
  const m = data.model;
  if (!m) throw new Error('Modele ' + id + ' introuvable sur Printables.');
  const stls = (m.stls || []).slice(0, 15);
  if (!stls.length) {
    return [{ json: { action, statut: 'SANS_STL', phrase_pour_utilisateur: 'Ce modèle n\'a pas de fichier STL téléchargeable' + QUI + ', seulement d\'autres formats. Le lien est dans la liste que je t\'ai envoyée.' } }];
  }
  const dest = DOSSIER + 'telecharges/' + m.id + '-' + String(m.slug || 'modele').slice(0, 60) + '/';
  fs.mkdirSync(dest, { recursive: true });
  const ok = [], ko = [];
  for (const f of stls) {
    try {
      const dl = await gql('GetDownloadLink',
        'mutation GetDownloadLink($id: ID!, $modelId: ID!, $fileType: DownloadFileTypeEnum!, $source: DownloadSourceEnum!) { getDownloadLink(id: $id, printId: $modelId, fileType: $fileType, source: $source) { ok output { link } } }',
        { id: f.id, modelId: m.id, fileType: 'stl', source: 'model_detail' });
      const link = dl.getDownloadLink && dl.getDownloadLink.output && dl.getDownloadLink.output.link;
      if (!link) { ko.push(f.name); continue; }
      const buf = await this.helpers.httpRequest({ method: 'GET', url: link, headers: { 'User-Agent': HEAD['User-Agent'] }, encoding: 'arraybuffer', timeout: 60000 });
      const nomFichier = String(f.name).replace(/[\\/:*?"<>|]/g, '_');
      fs.writeFileSync(dest + nomFichier, Buffer.from(buf));
      ok.push(nomFichier);
    } catch (e) { ko.push(f.name); }
  }
  if (!ok.length) throw new Error('Aucun fichier n\'a pu etre telecharge.');
  const phrase = 'C\'est téléchargé' + QUI + ' : ' + ok.length + ' fichier' + (ok.length > 1 ? 's' : '') + ' 3D de « ' + m.name + ' », rangé' + (ok.length > 1 ? 's' : '') + ' dans le dossier des téléchargements 3D.' + (ko.length ? ' ' + ko.length + ' fichier' + (ko.length > 1 ? 's n\'ont' : ' n\'a') + ' pas pu être récupéré.' : '');
  return [{ json: { action, statut: 'OK', modele: m.name, dossier: dest, fichiers: ok, echecs: ko, phrase_pour_utilisateur: phrase } }];
}

throw new Error('Action inconnue : ' + action + ' (chercher ou telecharger).');

// le prenom du profil : « , Camille » ; rien s'il manque
let QUI = ''; try { const p = String($env.ARCHI_UTILISATEUR || '').trim().slice(0, 30); if (p) QUI = ', ' + p; } catch (e) {}
const c = $('Catalogues').first().json;
const env = $input.first().json || {};
const ok = !env.error;
const noms = c.resultats.slice(0, 3).map(m => m.n + ', ' + m.nom).join(' ; ');
const phrase = ok
  ? `J'ai trouvé ${c.nb} modèles sur Printables${QUI}, je t'ai envoyé la liste avec les liens. Les trois premiers : ${noms}. Je télécharge lequel, ou je la conçois moi-même ?`
  : `J'ai trouvé ${c.nb} modèles sur Printables mais l'envoi de la liste a échoué. Les premiers : ${noms}. Je télécharge lequel, ou je la conçois moi-même ?`;
return [{ json: { statut: 'RESULTATS', liste_envoyee: ok, resultats: c.resultats.map(({ n, nom, auteur }) => ({ n, nom, auteur })), phrase_pour_utilisateur: phrase } }];

// le prenom du profil : « , Camille » ; rien s'il manque
let QUI = ''; try { const p = String($env.ARCHI_UTILISATEUR || '').trim().slice(0, 30); if (p) QUI = ', ' + p; } catch (e) {}
const c = $('Catalogues').first().json;
if (c.action === 'chercher') {
  return [{ json: { statut: 'RIEN', phrase_pour_utilisateur: `Je n'ai rien trouvé sur Printables pour « ${c.requete} »${QUI}. Je la conçois moi-même ?` } }];
}
return [{ json: c }];
